parameters.jsonOutput:
={
  "prompt": {{
    JSON.stringify(
      "You are a strict data normalizer for e-commerce products.\n" +
      "You MUST output valid JSON only.\n" +
      "No explanations, no markdown, no comments.\n" +
      "You MUST follow the JSON schema exactly.\n\n" +
      "- Do not add fields\n" +
      "- Do not omit required fields\n" +
      "- Use null when data is missing\n\n" +
      "Normalization rules:\n" +
      "1. Remove marketing text, store descriptions, shipping info\n" +
      "2. Remove website names from titles\n" +
      "3. Keep model numbers EXACTLY as-is\n" +
      "4. Normalize units:\n" +
      "   - W, bar, kg, L/min, m\n" +
      "5. Convert text numbers to numeric values when possible\n" +
      "6. Lowercase normalized_title except model codes\n" +
      "7. Extract only factual product attributes\n" +
      "8. Ignore duplicated content\n\n" +
      "embedding_text rules:\n" +
      "- concise (max ~40 words)\n" +
      "- include product type + key specs + model\n" +
      "- no marketing words\n\n" +
      "If unsure about a value → use null" +
      "\ncategory rules: (Choose exactly one category from this allowed list. If none match, return empty object, keywords between parentheses are used for increased context not to for absolute match):" +
      $json.target_categories)
  }},

  "metadata_description": {{
    JSON.stringify(
      $('Product Scrape Result Webhook').item.json.body.result.product.description || ""
    )
  }},

  "product_title": {{
    JSON.stringify(
      $('Product Scrape Result Webhook').item.json.body.result.product.title || ""
    )
  }},

  "url": {{
    JSON.stringify(
      $('Product Scrape Result Webhook').item.json.body.result.product.url || ""
    )
  }},

  "on_page_description": {{
    JSON.stringify(
      $('Product Scrape Result Webhook').item.json.body.result.product.on_page_details || {}
    )
  }},

  "jsonld_breadcumb_list": {{
    JSON.stringify(
      $('Product Scrape Result Webhook')
        .item
        .json
        .body
        .result
        .metadata
        .signals
        .breadcrumb_json_ld?.itemListElement
        ?.map(item => item.name)
        ?.join(" -> ") || ""
    )
  }}
}

