parameters.inputSchema:
{
  "type": ["object", "null"],
  "additionalProperties": false,
  "properties": {
    "product": {
      "type": ["object", "null"],
      "additionalProperties": false,
      "properties": {
        "normalized_title": {
          "type": "string",
          "minLength": 3,
          "description": "Cleaned title without brand suffix, normalized units, lowercase except model"
        },
        "embedding_text": {
          "type": "string",
          "minLength": 10,
          "description": "Compact semantic string for embeddings (MUST BE IN ENGLISH)"
        },
        "product_relevant_description": {
          "type": "string",
          "description": "Cleaned description without marketing text"
        },
        "price": {
          "type": ["float", "null"]
        },
        "availability": {
          "type": "string",
          "enum": ["InStock", "OutOfStock", "Unknown"]
        },
        "brand": {
          "type": ["string", "null"]
        },
        "category": {
          "type": ["string", "null"]
        },
        "model": {
          "type": ["string", "null"]
        },
        "specs": {
          "type": "object",
          "additionalProperties": {
            "type": ["string", "number", "null"]
          }
        }
      },
      "required": [
        "category",
        "brand",
        "normalized_title",
        "embedding_text",
        "product_relevant_description",
        "availability",
        "price",
        "specs"
      ]
    }
  }
}
